//! The OpenAPI document of the headless flow API (`docs/openapi/flows-v1.json`), generated by
//! utoipa from the handlers in [`super::browser`] and guarded by the drift test
//! `tests/openapi_flows_drift.rs` (`just openapi-update` regenerates it).
//!
//! Paths are relative to the tenant's base: `/t/{slug}` for path tenants, the root for the
//! default tenant, or the tenant's own host.

use utoipa::openapi::security::{ApiKey, ApiKeyValue, SecurityScheme};
use utoipa::openapi::tag::TagBuilder;
use utoipa::openapi::{Components, InfoBuilder, OpenApi, OpenApiBuilder, OpenApiVersion};

/// The name of the CSRF header security scheme.
pub(super) const CSRF_SCHEME: &str = "csrf";

/// The document's info, tags and the CSRF header scheme; the paths come from the router.
pub(super) fn base_document() -> OpenApi {
    let mut components = Components::new();
    components.add_security_scheme(
        CSRF_SCHEME,
        SecurityScheme::ApiKey(ApiKey::Header(ApiKeyValue::with_description(
            "X-CSRF-Token",
            "Browser mode: the flow's `csrf_token` from the previous answer, together with the \
             flow cookie the start answer set on the AnvilID origin (`credentials: \"include\"`).",
        ))),
    );
    OpenApiBuilder::new()
        .openapi(OpenApiVersion::Version31)
        .info(
            InfoBuilder::new()
                .title("AnvilID headless flow API")
                .version("v1")
                .description(Some(
                    "Drives the login, registration, recovery and verification flows of a tenant \
                     with JSON: the same flow engine, brute-force limits, CAPTCHA and sessions as \
                     the built-in pages. Paths are relative to the tenant base (`/t/{slug}`, the \
                     root for the default tenant, or the tenant host). Browser mode only: a \
                     same-site single-page app on an origin in the tenant's \
                     `headless.allowed_origins`, the flow cookie, the `X-CSRF-Token` header and \
                     `application/json` bodies. Clients must ignore unknown fields, steps, field \
                     kinds and methods. Errors are RFC 9457 problem details. See docs/HEADLESS.md.",
                ))
                .build(),
        )
        .components(Some(components))
        .tags(Some([TagBuilder::new()
            .name("flows")
            .description(Some("Self-service flows (browser mode)"))
            .build()]))
        .build()
}

/// The OpenAPI document of the headless flow API.
pub fn openapi() -> OpenApi {
    super::api_router().split_for_parts().1
}
